package com.example.leetcodetrainer.adaptive.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="learning_task_template") public class LearningTaskTemplate {
 @Id private UUID id; @Column(nullable=false,unique=true) private String code; @Enumerated(EnumType.STRING) @Column(nullable=false) private LearningTaskType taskType; @Enumerated(EnumType.STRING) @Column(nullable=false) private ReasoningProfileType profile; @Column(nullable=false) private String title; @Lob @Column(nullable=false) private String prompt; @Lob @Column(nullable=false) private String targetSkills; @Column(name="source_problem_slug",nullable=false) private String sourceProblemSlug; @Lob @Column(nullable=false) private String successCriteria; @Column(nullable=false) private boolean active; protected LearningTaskTemplate(){} public UUID getId(){return id;} public String getCode(){return code;} public LearningTaskType getTaskType(){return taskType;} public ReasoningProfileType getProfile(){return profile;} public String getTitle(){return title;} public String getPrompt(){return prompt;} public String getTargetSkills(){return targetSkills;} public String getSourceProblemSlug(){return sourceProblemSlug;} public String getSuccessCriteria(){return successCriteria;} }
